import numpy as np


def link(name, mu):
    mu = np.asarray(mu, dtype=float)
    if name == 'logit':
        return np.log(mu / (1 - mu))
    if name == 'log':
        return np.log(mu)
    if name == 'identity':
        return mu
    raise ValueError('unknown link: ' + name)


def inverse_link(name, eta):
    eta = np.asarray(eta, dtype=float)
    if name == 'logit':
        return 1 / (1 + np.exp(-eta))
    if name == 'log':
        return np.exp(eta)
    if name == 'identity':
        return eta
    raise ValueError('unknown link: ' + name)


def variance_function(family, mu):
    mu = np.asarray(mu, dtype=float)
    if family == 'binomial':
        return mu * (1 - mu)
    if family == 'poisson':
        return mu
    if family == 'gamma':
        return mu ** 2
    if family == 'gaussian':
        return np.ones_like(mu)
    raise ValueError('unknown family: ' + family)
